def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = [0] * 10
    for row in grid:
        for v in row:
            counts[v] += 1

    colors = sorted(range(10), key=lambda c: counts[c], reverse=True)
    background, line_color = colors[0], colors[1]

    rows = [r for r in range(h)
            if sum(v == line_color for v in grid[r]) >= 0.65 * w]
    cols = [c for c in range(w)
            if sum(grid[r][c] == line_color for r in range(h)) >= 0.65 * h]

    out = []
    for i in range(len(rows) - 1):
        out_row = []
        for j in range(len(cols) - 1):
            corners = (
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            )
            out_row.append(corners[0] if all(v == corners[0] for v in corners)
                           else background)
        out.append(out_row)

    while out and all(v == background for v in out[-1]):
        out.pop()
    while out and out[0] and all(row[-1] == background for row in out):
        for row in out:
            row.pop()

    return out
